import { useDarkMode } from '@/hooks/useDarkMode';
import { PALETTE, rgba } from '@/theme/tokens';

/** Account 风格页面 CSS 变量（亮/暗主题） */
export function usePageStyleVars(): React.CSSProperties {
  const [dark] = useDarkMode();
  return {
    '--page-border': dark ? 'rgba(255,255,255,0.08)' : 'rgba(0,0,0,0.07)',
    '--page-shadow': dark ? '0 2px 20px rgba(0,0,0,0.4)' : '0 2px 20px rgba(0,0,0,0.06)',
    '--page-hero-bg': dark
      ? `linear-gradient(135deg, ${rgba(PALETTE.deepNavy, 0.2)} 0%, ${rgba(PALETTE.deepNavy, 0.08)} 100%)`
      : `linear-gradient(135deg, ${rgba(PALETTE.deepNavy, 0.09)} 0%, ${rgba(PALETTE.deepNavy, 0.04)} 100%)`,
    '--page-row-hover': dark ? 'rgba(255,255,255,0.04)' : rgba(PALETTE.deepNavy, 0.04),
  } as React.CSSProperties;
}

export const PAGE_GRADIENTS = {
  blue: `linear-gradient(135deg, ${PALETTE.deepNavy} 0%, #4F6985 100%)`,
  green: `linear-gradient(135deg, #5F8B6E 0%, ${PALETTE.sageGreen} 100%)`,
  orange: `linear-gradient(135deg, ${PALETTE.terracotta} 0%, ${PALETTE.deepNavy} 100%)`,
  purple: `linear-gradient(135deg, ${PALETTE.deepNavy} 0%, ${PALETTE.terracotta} 100%)`,
  cyan: `linear-gradient(135deg, ${PALETTE.deepNavy} 0%, ${PALETTE.lightMist} 100%)`,
  indigo: `linear-gradient(135deg, ${PALETTE.deepNavy} 0%, ${PALETTE.sageGreen} 100%)`,
} as const;
